// familytree service worker — generated by tools/build.js (webapp-pwa-standards §12). Do not edit in dist/.
const VERSION = new URL(self.location.href).searchParams.get('v') || 'dev';
const CACHE = 'familytree-shell-v' + VERSION;
const SHELL = ["./","./index.html","./app.js","./shell.js","./style.css","./manifest.json","./favicon.svg","./icon.png","./icon-512.png"];

self.addEventListener('install', (e) => {
	e.waitUntil(caches.open(CACHE).then((c) => c.addAll(SHELL)).then(() => self.skipWaiting()));
});
self.addEventListener('activate', (e) => {
	e.waitUntil(
		caches.keys()
			.then((keys) => Promise.all(keys.filter((k) => k.startsWith('familytree-shell-v') && k !== CACHE).map((k) => caches.delete(k))))
			.then(() => self.clients.claim())
	);
});
self.addEventListener('fetch', (e) => {
	const req = e.request;
	if (req.method !== 'GET') return;                       // never cache writes
	const url = new URL(req.url);
	// NETWORK-ONLY for live data + the Firebase SDK CDN — IndexedDB (§11) is the offline data story,
	// a stale cached record/SDK is worse than a failed fetch.
	if (url.hostname.endsWith('firebasedatabase.app') || url.hostname === 'www.gstatic.com' || url.hostname.endsWith('googleapis.com')) {
		return;                                               // let the network handle it (default)
	}
	if (url.origin !== self.location.origin) return;
	// NAVIGATION (the HTML) — NETWORK-FIRST. The HTML points at the ?v=-stamped assets, so if it were
	// cache-first a new deploy could NEVER reach the device: it would keep serving the old index.html
	// (→ old app.js) and never fetch the new bundle (the Android "stuck on stale shell → blank" bug).
	// Network-first = always the latest HTML when online; cached index.html only when offline.
	if (req.mode === 'navigate') {
		e.respondWith(
			fetch(req).then((res) => {
				if (res && res.ok) { const copy = res.clone(); caches.open(CACHE).then((c) => c.put('./index.html', copy)); }
				return res;
			}).catch(() => caches.match('./index.html').then((h) => h || caches.match('./')))
		);
		return;
	}
	// SHELL ASSETS (same-origin non-navigation: app.js/style.css/icons, each referenced with a ?v=<stamp>
	// cache-buster). NETWORK-FIRST: a new deploy changes ?v=, and we MUST fetch the new bytes when
	// online — a cache-first (or ignoreSearch) match would serve the FIRST-cached app.js forever and
	// freeze the app at the old version even as the HTML updates (the "stale app.js, new HTML" bug).
	// So: try network first (refresh the cache under the BARE path so offline has the latest), and only
	// fall back to the cached copy when the network fails (offline). Offline match uses ignoreSearch so
	// the ?v= request still resolves to the bare-cached asset.
	e.respondWith(
		fetch(req).then((res) => {
			if (res && res.ok && res.type === 'basic') {
				const copy = res.clone();
				caches.open(CACHE).then((c) => c.put(new Request(url.origin + url.pathname), copy));
			}
			return res;
		}).catch(() => caches.match(req, { ignoreSearch: true }))
	);
});
